/* Translated from linux/mtd/spinand.h. External Linux/SPI symbols are dependencies. */

macro_rules! SPINAND_RESET_1S_0_0_OP { () => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0xff,1), SPI_MEM_OP_NO_ADDR!, SPI_MEM_OP_NO_DUMMY!, SPI_MEM_OP_NO_DATA!) }; }
macro_rules! SPINAND_WR_EN_1S_0_0_OP { () => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x06,1), SPI_MEM_OP_NO_ADDR!, SPI_MEM_OP_NO_DUMMY!, SPI_MEM_OP_NO_DATA!) }; }
macro_rules! SPINAND_WR_DIS_1S_0_0_OP { () => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x04,1), SPI_MEM_OP_NO_ADDR!, SPI_MEM_OP_NO_DUMMY!, SPI_MEM_OP_NO_DATA!) }; }
macro_rules! SPINAND_READID_1S_1S_1S_OP { ($naddr:expr,$ndummy:expr,$buf:expr,$len:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x9f,1),SPI_MEM_OP_ADDR!($naddr,0,1),SPI_MEM_OP_DUMMY!($ndummy,1),SPI_MEM_OP_DATA_IN!($len,$buf,1)) }; }
macro_rules! SPINAND_SET_FEATURE_1S_1S_1S_OP { ($reg:expr,$v:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x1f,1),SPI_MEM_OP_ADDR!(1,$reg,1),SPI_MEM_OP_NO_DUMMY!,SPI_MEM_OP_DATA_OUT!(1,$v,1)) }; }
macro_rules! SPINAND_GET_FEATURE_1S_1S_1S_OP { ($reg:expr,$v:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x0f,1),SPI_MEM_OP_ADDR!(1,$reg,1),SPI_MEM_OP_NO_DUMMY!,SPI_MEM_OP_DATA_IN!(1,$v,1)) }; }
macro_rules! SPINAND_BLK_ERASE_1S_1S_0_OP { ($a:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0xd8,1),SPI_MEM_OP_ADDR!(3,$a,1),SPI_MEM_OP_NO_DUMMY!,SPI_MEM_OP_NO_DATA!) }; }
macro_rules! SPINAND_PAGE_READ_1S_1S_0_OP { ($a:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x13,1),SPI_MEM_OP_ADDR!(3,$a,1),SPI_MEM_OP_NO_DUMMY!,SPI_MEM_OP_NO_DATA!) }; }

/* The remaining operation macros retain the original SPI_MEM_OP composition. */
macro_rules! spinand_cache_op { ($cmd:expr,$aw:expr,$al:expr,$nd:expr,$dw:expr,$len:expr,$buf:expr,$freq:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!($cmd,1),SPI_MEM_OP_ADDR!($al,$aw,1),SPI_MEM_OP_DUMMY!($nd,1),SPI_MEM_OP_DATA_IN!($len,$buf,$dw),SPI_MEM_OP_MAX_FREQ!($freq)) }; }
macro_rules! SPINAND_PAGE_READ_FROM_CACHE_1S_1S_1S_OP { ($a:expr,$n:expr,$b:expr,$l:expr,$f:expr) => { spinand_cache_op!(0x03,2,$a,$n,1,$l,$b,$f) }; }
macro_rules! SPINAND_PAGE_READ_FROM_CACHE_FAST_1S_1S_1S_OP { ($a:expr,$n:expr,$b:expr,$l:expr,$f:expr) => { spinand_cache_op!(0x0b,2,$a,$n,1,$l,$b,$f) }; }
macro_rules! SPINAND_PAGE_READ_FROM_CACHE_3A_1S_1S_1S_OP { ($a:expr,$n:expr,$b:expr,$l:expr,$f:expr) => { spinand_cache_op!(0x03,3,$a,$n,1,$l,$b,$f) }; }
macro_rules! SPINAND_PAGE_READ_FROM_CACHE_FAST_3A_1S_1S_1S_OP { ($a:expr,$n:expr,$b:expr,$l:expr,$f:expr) => { spinand_cache_op!(0x0b,3,$a,$n,1,$l,$b,$f) }; }
macro_rules! SPINAND_PROG_EXEC_1S_1S_0_OP { ($a:expr) => { SPI_MEM_OP!(SPI_MEM_OP_CMD!(0x10,1),SPI_MEM_OP_ADDR!(3,$a,1),SPI_MEM_OP_NO_DUMMY!,SPI_MEM_OP_NO_DATA!) }; }

